import json, os

workspace = '/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-2/play/users/u001/system/state/workspace'

# Load demos from state to understand the exact pattern
state_file = os.path.join(workspace, 'state')
if os.path.exists(state_file):
    with open(state_file) as f:
        state = json.load(f)

if 'demo_input' in state and 'demo_output' in state:
    demo_input = state['demo_input']
    demo_output = state['demo_output']

    print("=== DEMO INPUT ===")
    for row in demo_input:
        print(' '.join(map(str, row)))

    print("\n=== DEMO OUTPUT ===")
    for row in demo_output:
        print(' '.join(map(str, row)))

    # Compare differences
    print("\n=== DIFFERENCE ANALYSIS ===")
    h_in, w_in = len(demo_input), len(demo_input[0])
    h_out, w_out = len(demo_output), len(demo_output[0])

    diff_cells = []
    for r in range(min(h_in, h_out)):
        for c in range(min(w_in, w_out)):
            if demo_input[r][c] != demo_output[r][c]:
                diff_cells.append((r, c, demo_input[r][c], demo_output[r][c]))

    if diff_cells:
        print(f"Changed cells ({len(diff_cells)}):")
        for r, c, inp, outp in sorted(diff_cells):
            print(f"  ({r},{c}): {inp} → {outp}")
    else:
        print("NO CHANGES - identity transformation!")
else:
    print("No demo data found in state!")

